HISTORICAL_RELEASE_SCOPE = [node for node in ast.parse(subprocess.check_output(['git', 'show',
    'fd16cc2cbbec84c212f315d4b735ea0ce8a6cd6a:scripts/production-release/remote-deploy.py'],
    cwd=Path(__file__).resolve().parents[2])).body
    if isinstance(node, ast.FunctionDef) and node.name == 'release_services']
if len(HISTORICAL_RELEASE_SCOPE) != 1:
    raise AssertionError('Pinned historical release scope unavailable')


@contextmanager
def synthetic_historical_release_scope():
    """Reproduce old receipts locally without reopening any current CLI entry."""
    namespace = dict(vars(deployment))
    exec(compile(ast.Module(body=HISTORICAL_RELEASE_SCOPE, type_ignores=[]), 'pinned-historical-release-scope', 'exec'), namespace)
    with patch.object(deployment, 'release_services', namespace['release_services']), \
         patch.object(deployment, 'require_workspace_publication_scope'):
        # These receipts predate the SQLite workspace; its real guard is tested separately.
        yield


class ReleaseScopeTests(unittest.TestCase):
    def test_admin_only_never_selects_api_workers_or_migration_image(self):
        services, images = deployment.release_services(True, [])
        self.assertEqual(services, ('admin',))
        self.assertEqual(images, ('admin',))

    def test_migration_blocks_admin_only_before_any_service_switch(self):
        with self.assertRaisesRegex(RuntimeError, 'contains migrations'):
            deployment.release_services(True, ['20261001_example'])

    def test_other_scope_retains_the_full_release(self):
        services, images = deployment.release_services(False, ['20261001_example'])
        self.assertEqual(services, deployment.CURRENT_SERVICES)
        self.assertNotIn('auto-registration', services)
        self.assertEqual(images, ('media-resolver', 'auto-recharge', 'api', 'admin', 'migrate'))


    def test_edge_changes_switch_caddy_without_building_an_edge_image(self):
        services, images = deployment.release_services(False, [], True)
        self.assertEqual(services, (*deployment.CURRENT_SERVICES, 'caddy'))
        self.assertEqual(images, ('media-resolver', 'auto-recharge', 'api', 'admin', 'migrate'))
        with self.assertRaisesRegex(RuntimeError, 'edge configuration'):
            deployment.release_services(True, [], True)

    def test_only_caddy_can_use_running_status_without_container_health(self):
        state = {'status': 'running', 'health': None}
        with patch.object(deployment, 'service_state', return_value=state), \
                patch.object(deployment.time, 'sleep'):
            self.assertEqual(deployment.wait_healthy(None, 'caddy'), state)
            with self.assertRaisesRegex(RuntimeError, 'did not become healthy'):
                deployment.wait_healthy(None, 'admin')

    def test_current_release_excludes_registration_image_reference(self):
        services, images = deployment.release_services(False, [], True)
        tags = {service: 'fixture-' + service for service in images}
        references = deployment.release_image_references(services, images, 'fixture-registry', tags)
        self.assertNotIn('auto-registration', references)
        self.assertEqual(references['auto-recharge'], 'fixture-registry:fixture-auto-recharge')
        self.assertIn('migrate', references)
        self.assertNotIn('caddy', references)
        services, images = deployment.release_services(True, [])
        self.assertEqual(deployment.release_image_references(services, images, 'fixture-registry', tags),
                         {'admin': 'fixture-registry:fixture-admin'})

    def test_old_baseline_and_split_layout_select_only_existing_services(self):
        with tempfile.TemporaryDirectory() as root:
            directory = Path(root)
            compose = directory / 'docker-compose.aws-mysql.yml'
            compose.write_text('services:\n  auto-recharge:\n  api:\n')
            self.assertNotIn('auto-registration', deployment.production_services(directory))
            compose.write_text('services:\n  auto-recharge:\n  auto-registration:\n  api:\n')
            self.assertEqual(deployment.production_services(directory), deployment.ALL_SERVICES)

    def test_transition_rollback_removes_only_the_added_worker(self):
        with patch.object(deployment, 'compose', side_effect=['', '']) as compose, \
                patch.object(deployment, 'service_state') as state:
            deployment.rollback_service('old', 'new', 'auto-registration', {})
        self.assertEqual(compose.call_args_list[0].args,
                         ('new', 'rm', '-s', '-f', 'auto-registration'))
        self.assertEqual(compose.call_args_list[1].args,
                         ('new', 'ps', '-q', '--all', 'auto-registration'))
        state.assert_not_called()
        with patch.object(deployment, 'compose', side_effect=['', 'still-running']):
            with self.assertRaisesRegex(RuntimeError, 'worker remains'):
                deployment.rollback_service('old', 'new', 'auto-registration', {})
        with patch.object(deployment, 'compose') as compose:
            with self.assertRaisesRegex(RuntimeError, 'Unexpected added'):
                deployment.rollback_service('old', 'new', 'api', {})
        compose.assert_not_called()

    def test_later_split_rollback_restores_existing_registration_image(self):
        state = {'image': 'sha256:fixture-old'}
        with patch.object(deployment, 'compose') as compose, \
                patch.object(deployment, 'service_state', return_value=state), \
                patch.object(deployment, 'wait_healthy') as health:
            deployment.rollback_service('old', 'new', 'auto-registration', {'auto-registration': state})
        self.assertEqual(compose.call_args.args,
                         ('old', 'up', '-d', '--no-deps', '--no-build', '--pull', 'never',
                          '--force-recreate', 'auto-registration'))
        health.assert_called_once_with('old', 'auto-registration')

    def test_registration_selection_is_rejected_before_release_operations(self):
        for tokens in [
            ['--registration-worker-95'],
            ['--registration-worker-96'],
            ['--check-fixed-registration-scope'],
            ['--prepare-fixed-registration-build', '--registration-profile', 'registration-worker-92-20261007'],
            ['--historical-finance-continuation'],
            ['--api-registration-only'],
            ['--prepare-api-registration-build'],
            ['--write-api-registration-build-proof'],
            ['--api-registration-verify'],
            ['--api-registration-preflight'],
            ['--api-registration-handoff'],
            ['--api-registration-business'],
            ['--api-registration-handoff-observe'],
            ['--api-registration-handoff-recover'],
        ]:
            with self.subTest(tokens=tokens):
                with self.assertRaisesRegex(RuntimeError, 'registration releases are disabled'):
                    deployment.reject_retired_registration_selection(tokens)
                result = subprocess.run(['python3', '-B', str(Path(__file__).with_name('remote-deploy.py')), *tokens],
                    capture_output=True, text=True)
                self.assertNotEqual(result.returncode, 0)
                self.assertIn('registration releases are disabled', result.stderr)
        deployment.reject_retired_registration_selection(['--recharge-pro-6f5'])
        deployment.reject_retired_registration_selection(
            ['--api-registration-readback', '--expected-current', 'a' * 40])
        with self.assertRaisesRegex(RuntimeError, 'registration releases are disabled'):
            deployment.release_services(False, [], registration_only=True)

    def test_retired_api_registration_stops_before_scope_or_runtime_access(self):
        with patch.object(deployment, 'api_admin_scope') as scope, \
                patch.object(deployment, 'compose') as compose, \
                patch.object(deployment.subprocess, 'run') as transport, \
                patch('sys.argv', ['remote-deploy.py', '--api-registration-only']):
            with self.assertRaisesRegex(RuntimeError, 'registration releases are disabled'):
                deployment.main()
        scope.assert_not_called()
        compose.assert_not_called()
        transport.assert_not_called()

    def test_registration_build_push_and_dispatch_stop_before_transport(self):
        environment = {'PATH': '/usr/bin:/bin', 'HISTORICAL_EXCEPTION': 'registration-worker-95-20261008'}
        for name in ('build-images.sh', 'push-images.sh', 'dispatch.sh'):
            with self.subTest(name=name):
                result = subprocess.run(['bash', str(Path(__file__).with_name(name))],
                    env=environment, capture_output=True, text=True)
                self.assertNotEqual(result.returncode, 0)
                self.assertIn('registration releases are disabled', result.stderr)


class CurrentJobDatabaseTests(unittest.TestCase):
    def setUp(self):
        self.directory = Path('/synthetic-release')
        self.current = 'id_business_v2_partial_cleanup_20261005_v1'
        self.old = 'id_business_v2_cutover_20260827_v5'
        self.values = {'MYSQL_DATABASE': self.current,
            'DATABASE_URL': 'mysql://id_business_app:synthetic-private-marker@mysql/' + self.current}
        self.environment = patch.object(deployment, 'environment_values', return_value=self.values)
        self.environment.start()
        self.addCleanup(self.environment.stop)
        self.identity = {'configuredDatabase': self.current, 'actualDatabase': self.current}

    def test_live_api_and_configuration_agree_without_credentials_in_probe_or_result(self):
        with patch.object(deployment, 'compose', return_value=json.dumps(self.identity)) as compose:
            self.assertEqual(deployment.current_job_database(self.directory), self.current)
        self.assertEqual(compose.call_args.args[:6],
                         (self.directory, 'exec', '-T', 'api', 'node', '-e'))
        self.assertEqual(compose.call_args.kwargs, {'timeout': 30})
        self.assertIn('SELECT DATABASE() AS databaseName', compose.call_args.args[-1])
        self.assertNotIn('synthetic-private-marker', repr(compose.call_args))

    def test_invalid_configurations_stop_before_live_probe(self):
        for update in ({'MYSQL_DATABASE': 'new; DROP DATABASE old'},
                       {'MYSQL_DATABASE': 'a' * 65},
                       {'DATABASE_URL': 'mysql://id_business_app:synthetic@mysql/' + self.old},
                       {'DATABASE_URL': 'mysql://root:synthetic@mysql/' + self.current},
                       {'DATABASE_URL': 'mysql://id_business_app:synthetic@external/' + self.current},
                       {'DATABASE_URL': 'mysql://id_business_app:synthetic@mysql:bad/' + self.current},
                       {'DATABASE_URL': 'mysql://id_business_app:synthetic@mysql/' + self.current + '#raw'}):
            with self.subTest(update=sorted(update)), \
                    patch.object(deployment, 'environment_values', return_value={**self.values, **update}), \
                    patch.object(deployment, 'compose') as compose:
                with self.assertRaisesRegex(RuntimeError, '^Production database configuration invalid$'):
                    deployment.current_job_database(self.directory)
                compose.assert_not_called()

    def test_configured_or_actual_live_api_database_mismatch_prevents_every_lease_query(self):
        for field in self.identity:
            for guard in (deployment.assert_no_active_recharge, deployment.assert_no_active_registration):
                with self.subTest(field=field, guard=guard.__name__), \
                        patch.object(deployment, 'registration_runtime_state', return_value={
                            'supported': True, 'registrationBusy': False, 'registrationWindowRetained': False}), \
                        patch.object(deployment, 'compose', return_value=json.dumps({
                            **self.identity, field: self.old})) as compose:
                    with self.assertRaisesRegex(RuntimeError, '^Production database identity mismatch$'):
                        guard(self.directory)
                    self.assertEqual(compose.call_count, 1)
                    self.assertEqual(compose.call_args.args[3], 'api')

    def test_missing_malformed_or_extra_live_identity_fails_without_raw_error(self):
        for value in ('not-json', '[]', '{}', json.dumps({**self.identity, 'private': 'raw-private-marker'}),
                      json.dumps({**self.identity, 'actualDatabase': 'db;secret'})):
            with self.subTest(value_type=type(value).__name__), \
                    patch.object(deployment, 'compose', return_value=value):
                with self.assertRaisesRegex(RuntimeError, '^Production database identity unavailable$'):
                    deployment.current_job_database(self.directory)
        with patch.object(deployment, 'compose', side_effect=RuntimeError('raw-private-marker')):
            with self.assertRaisesRegex(RuntimeError, '^Production database identity unavailable$') as error:
                deployment.current_job_database(self.directory)
            self.assertTrue(error.exception.__suppress_context__)

    def test_active_new_database_lease_cannot_be_hidden_by_idle_mysql_initdb_database(self):
        for guard in (deployment.assert_no_active_recharge, deployment.assert_no_active_registration):
            calls = []
            def compose(directory, *args, **kwargs):
                calls.append(args)
                if args[:5] == ('exec', '-T', 'api', 'node', '-e'):
                    return json.dumps(self.identity)
                self.assertTrue(args[:7] == ('exec', '-e', 'MYSQL_DATABASE=' + self.current,
                                            '-T', 'mysql', 'sh', '-c')
                                or args[:5] == ('exec', '-T', 'mysql', 'sh', '-c'))
                # The retained mysql container's default would read idle old=0.
                database = args[2].partition('=')[2] if args[1] == '-e' else self.old
                return '1' if database == self.current else '0'
            with self.subTest(guard=guard.__name__), \
                    patch.object(deployment, 'registration_runtime_state', return_value={
                        'supported': True, 'registrationBusy': False, 'registrationWindowRetained': False}), \
                    patch.object(deployment, 'compose', side_effect=compose):
                with self.assertRaisesRegex(RuntimeError, 'Active .* jobs prevent release'):
                    guard(self.directory)
            self.assertEqual(len(calls), 2)
            self.assertEqual(calls[-1][:7], ('exec', '-e', 'MYSQL_DATABASE=' + self.current,
                                           '-T', 'mysql', 'sh', '-c'))
            self.assertNotIn('synthetic-private-marker', repr(calls))
            self.assertIn('$MYSQL_ROOT_PASSWORD', calls[-1][-1])

    def test_actual_container_probe_uses_runtime_configuration_and_connected_database(self):
        # Execute the real fixed JavaScript with only Prisma's database reads stubbed.
        import subprocess
        for actual in (self.current, self.old):
            def compose(directory, *args, **kwargs):
                probe = args[-1]
                wrapper = '''const vm=require('node:vm');
const actual=''' + json.dumps(actual) + ''';
vm.runInNewContext(''' + json.dumps(probe) + ''', {URL,console,process,
require(name){if(name!=='@prisma/client')throw Error();return {PrismaClient:class {
 async $queryRawUnsafe(sql){if(sql!=='SELECT DATABASE() AS databaseName')throw Error();
 return [{databaseName:actual}];} async $disconnect(){}
}};}});'''
                result = subprocess.run(['node', '-e', wrapper], capture_output=True, text=True,
                    env={**deployment.os.environ, 'DATABASE_URL': self.values['DATABASE_URL']}, timeout=10)
                self.assertEqual(result.returncode, 0, result.stderr)
                return result.stdout
            with self.subTest(actual_matches=actual == self.current), \
                    patch.object(deployment, 'compose', side_effect=compose):
                if actual == self.current:
                    self.assertEqual(deployment.current_job_database(self.directory), self.current)
                else:
                    with self.assertRaisesRegex(RuntimeError, '^Production database identity mismatch$'):
                        deployment.current_job_database(self.directory)


class RegistrationReleaseGuardTests(unittest.TestCase):
    def setUp(self):
        self.database = sqlite3.connect(':memory:')
        self.addCleanup(self.database.close)
        self.database.execute('CREATE TABLE id_business_v2_registration_jobs '
                              '(state TEXT, lease_until TEXT, browser_profile_id TEXT)')
        self.database.create_function('UTC_TIMESTAMP', 1, lambda _: '2026-10-03 00:00:00')
        self.idle = {'supported': True, 'registrationBusy': False,
                     'registrationWindowRetained': False}
        self.layout = patch.object(deployment, 'has_registration_worker', return_value=False)
        self.layout.start()
        self.addCleanup(self.layout.stop)
        self.current_database = patch.object(deployment, 'current_job_database', return_value='synthetic_current')
        self.current_database.start()
        self.addCleanup(self.current_database.stop)

    def row(self, state, lease='2026-10-03 01:00:00', profile='reg_original'):
        self.database.execute('INSERT INTO id_business_v2_registration_jobs VALUES (?, ?, ?)',
                              (state, lease, profile))

    def mysql(self, directory, *args, **kwargs):
        self.assertEqual(args[:7], ('exec', '-e', 'MYSQL_DATABASE=synthetic_current',
                                    '-T', 'mysql', 'sh', '-c'))
        sql = re.search(r'-e "([^"]+)"$', args[-1]).group(1)
        # Execute the actual gate predicate with only MySQL dialect conversions.
        sql = re.sub(r'0x([0-9a-f]+)',
                     lambda match: "'" + bytes.fromhex(match.group(1)).decode() + "'", sql)
        sql = sql.replace('LEFT(browser_profile_id, 4)', 'substr(browser_profile_id, 1, 4)')
        return str(self.database.execute(sql).fetchone()[0])

    def guard(self, runtime=None):
        with patch.object(deployment, 'registration_runtime_state',
                          return_value=self.idle if runtime is None else runtime), \
                patch.object(deployment, 'compose', side_effect=self.mysql):
            deployment.assert_no_active_registration(None)

    def test_live_running_and_verification_attempts_block_even_before_profile_receipt(self):
        for state in ('running', 'awaiting_email', 'awaiting_user'):
            with self.subTest(state=state):
                self.database.execute('DELETE FROM id_business_v2_registration_jobs')
                self.row(state, profile=None)
                with self.assertRaisesRegex(RuntimeError, 'Active registration jobs'):
                    self.guard()

    def test_history_completed_cancelled_queued_and_expired_rows_do_not_invent_windows(self):
        for state in ('completed', 'cancelled', 'partial'):
            self.row(state)
        self.row('queued', lease=None, profile=None)
        self.row('running', lease='2026-10-02 23:00:00')
        self.guard()

    def test_running_worker_or_retained_partial_window_blocks_without_sql_guessing(self):
        self.row('partial', lease=None)
        for field in ('registrationBusy', 'registrationWindowRetained'):
            with self.subTest(field=field), \
                    patch.object(deployment, 'registration_runtime_state',
                                 return_value={**self.idle, field: True}), \
                    patch.object(deployment, 'compose') as sql:
                with self.assertRaisesRegex(RuntimeError, 'Active registration jobs'):
                    deployment.assert_no_active_registration(None)
                sql.assert_not_called()

    def test_legacy_worker_allows_old_local_jobs_and_history_without_builtin_window(self):
        self.row('awaiting_user', profile='bitbrowser_original')
        self.row('running', profile=None)
        self.row('partial')
        self.guard({'supported': False})

    def test_legacy_worker_cannot_bypass_an_explicit_live_builtin_attempt(self):
        self.row('running')
        with self.assertRaisesRegex(RuntimeError, 'Active registration jobs'):
            self.guard({'supported': False})

    def test_admin_only_keeps_recharge_gate_without_interrupting_registration(self):
        with patch.object(deployment, 'assert_no_active_recharge') as recharge, \
                patch.object(deployment, 'assert_no_active_registration') as registration:
            deployment.assert_no_active_jobs(None, worker_changes=False)
        recharge.assert_called_once_with(None)
        registration.assert_not_called()
        with patch.object(deployment, 'assert_no_active_recharge',
                          side_effect=RuntimeError('Active recharge jobs prevent release')), \
                patch.object(deployment, 'assert_no_active_registration') as registration:
            with self.assertRaisesRegex(RuntimeError, 'Active recharge jobs'):
                deployment.assert_no_active_jobs(None, worker_changes=True)
        registration.assert_not_called()

    def test_full_switch_preserves_both_independent_guards(self):
        with patch.object(deployment, 'assert_no_active_recharge') as recharge, \
                patch.object(deployment, 'assert_no_active_registration') as registration:
            deployment.assert_no_active_jobs('current', worker_changes=True)
        recharge.assert_called_once_with('current')
        registration.assert_called_once_with('current')

    def test_invalid_or_unreadable_runtime_receipt_fails_closed_without_raw_error(self):
        values = ('not-json', '[]', '{"supported":0}',
                  json.dumps({**self.idle, 'registrationBusy': 0}),
                  json.dumps({**self.idle, 'unexpected': 'fixture-sensitive-value'}))
        for value in values:
            with self.subTest(value=value), patch.object(deployment, 'compose', return_value=value):
                with self.assertRaisesRegex(RuntimeError, 'Registration runtime guard unavailable'):
                    deployment.registration_runtime_state(None)
        with patch.object(deployment, 'compose',
                          side_effect=RuntimeError('fixture-sensitive-value')):
            with self.assertRaisesRegex(RuntimeError, '^Registration runtime guard unavailable$'):
                deployment.registration_runtime_state(None)

    def execute_probe(self, response_value=None, error=None, split=False):
        opener = MagicMock()
        if error is not None:
            opener.open.side_effect = error
        else:
            opener.open.return_value.__enter__.return_value.read.return_value = (
                json.dumps(response_value).encode())

        def container(directory, *args, **kwargs):
            service = 'auto-registration' if split else 'auto-recharge'
            self.assertEqual(args[:5], ('exec', '-T', service, 'python', '-c'))
            stdout = io.StringIO()
            with patch('urllib.request.build_opener', return_value=opener), \
                    patch.dict(deployment.os.environ, {'AUTO_RECHARGE_WORKER_TOKEN': 'fixture-token'}), \
                    redirect_stdout(stdout):
                try:
                    exec(args[-1], {})
                except SystemExit:
                    raise RuntimeError('container probe failed') from None
            return stdout.getvalue()

        with patch.object(deployment, 'compose', side_effect=container), \
                patch.object(deployment, 'has_registration_worker', return_value=split):
            result = deployment.registration_runtime_state(None)
        request = opener.open.call_args.args[0]
        self.assertEqual(request.full_url, 'http://127.0.0.1:8051/registration/health')
        self.assertEqual(request.get_header('X-recharge-worker'), 'fixture-token')
        self.assertNotIn('fixture-token', json.dumps(result))
        return result

    def test_authenticated_probe_returns_only_boolean_queue_proof(self):
        for split in (False, True):
            with self.subTest(split=split):
                result = self.execute_probe({'ready': True, 'engine': 'camoufox',
                                             'registrationBusy': False, 'registrationWindowRetained': False,
                                             **({'workerRole': 'registration'} if split else {}),
                                             'extra': 'fixture-sensitive-value'}, split=split)
                self.assertEqual(result, self.idle)

    def test_split_worker_requires_registration_role_without_legacy_fallback(self):
        for role in (None, 'recharge', 'unrecognized'):
            value = {'ready': True, 'engine': 'camoufox',
                     'registrationBusy': False, 'registrationWindowRetained': False}
            if role is not None:
                value['workerRole'] = role
            with self.subTest(role=role), \
                    self.assertRaisesRegex(RuntimeError, 'Registration runtime guard unavailable'):
                self.execute_probe(value, split=True)

    def test_only_legacy_404_is_supported_not_auth_failure_redirect_or_timeout(self):
        from urllib.error import HTTPError
        self.assertEqual(self.execute_probe(error=HTTPError('unused', 404, 'old', {}, None)),
                         {'supported': False})
        with self.assertRaisesRegex(RuntimeError, 'Registration runtime guard unavailable'):
            self.execute_probe(error=HTTPError('unused', 404, 'split', {}, None), split=True)
        for status in (301, 401, 403, 500):
            with self.subTest(status=status), \
                    self.assertRaisesRegex(RuntimeError, 'Registration runtime guard unavailable'):
                self.execute_probe(error=HTTPError('unused', status, 'failure', {}, None))
        with self.assertRaisesRegex(RuntimeError, 'Registration runtime guard unavailable'):
            self.execute_probe(error=TimeoutError('fixture-sensitive-value'))

    def test_new_worker_without_boolean_proof_or_readiness_fails_closed(self):
        for value in ({'ready': True, 'engine': 'camoufox'},
                      {'ready': False, 'engine': 'camoufox',
                       'registrationBusy': False, 'registrationWindowRetained': False},
                      {'ready': True, 'engine': 'camoufox',
                       'registrationBusy': 'false', 'registrationWindowRetained': False}):
            with self.subTest(value=value), \
                    self.assertRaisesRegex(RuntimeError, 'Registration runtime guard unavailable'):
                self.execute_probe(value)


class CommandFailureSummaryTests(unittest.TestCase):
    def setUp(self):
        self.environment = patch.dict(deployment.os.environ)
        self.environment.start()
        self.addCleanup(self.environment.stop)
        deployment.os.environ.pop('DIAGNOSTIC_COMMAND_ID', None)

    def online_fixture(self):
        receipt = {'status': 'ONLINE_RECHARGE_FAILED_BEFORE_SWITCH', 'step': 'images',
            'code': 'ONLINE_RECHARGE_STEP_FAILED', 'errorType': 'RuntimeError', 'rollbackOk': True,
            'rollback': {}, 'servicesAttempted': [], 'candidateCommit': '28a3ba4ffd17d36001b1104c97394f5ae871d73d',
            'previousCommit': '0a03fa28e6b844a18833d5c63f1de700f091fc64',
            'migration': {'name': '20261009093000_online_recharge',
                'sha256': '44966182c1bf38290b01f665a4c2c863b052677c5e0024b900137f1d7f11eb95',
                'status': 'PENDING', 'schemaVerified': True, 'appliedMigrationsSha256': 'a' * 64, 'performed': False},
            'migrationAttempted': False, 'inverseMigrationPerformed': False, 'mediaVolumeDeleted': False,
            'currentPointsToCandidate': False, 'receiptPersisted': True}
        invocation = {'CommandId': 'ab33d2e0-6135-47ed-8f20-e2defd7c82cd', 'Status': 'Failed', 'ResponseCode': 1,
            'StandardOutputContent': json.dumps(receipt), 'StandardErrorContent': 'fixture-sensitive-stderr',
            'Private': 'fixture-sensitive-envelope'}
        return receipt, invocation

    def online_summary(self, receipt, invocation):
        return deployment.command_failure_summary({**invocation, 'StandardOutputContent': json.dumps(receipt)})

    def assert_online_rejected(self, receipt, invocation):
        result = self.online_summary(receipt, invocation)
        self.assertNotIn('candidateCommit', result)
        self.assertNotIn('migration', result)
        self.assertNotIn('fixture-sensitive', json.dumps(result))

    def test_online_failure_projects_only_controlled_fields_and_original_candidate(self):
        receipt, invocation = self.online_fixture()
        deployment.os.environ['DIAGNOSTIC_COMMAND_ID'] = invocation['CommandId']
        deployment.os.environ['RELEASE_COMMIT'] = 'b' * 40
        result = self.online_summary(receipt, invocation)
        expected = {name: receipt[name] for name in ('status', 'step', 'code', 'rollbackOk', 'servicesAttempted',
                                                   'candidateCommit', 'previousCommit')}
        expected['commandId'] = invocation['CommandId']
        expected['failureReceiptSha256'] = hashlib.sha256(json.dumps(receipt, sort_keys=True, separators=(',', ':')).encode()).hexdigest()
        expected['migration'] = {name: receipt['migration'][name] for name in ('status', 'performed', 'name', 'sha256', 'schemaVerified')}
        self.assertEqual(result, expected)
        self.assertNotIn('fixture-sensitive', json.dumps(result))
        self.assertNotIn('appliedMigrationsSha256', result['migration'])

    def test_online_failure_hash_binds_complete_validated_receipt_independent_of_json_order(self):
        receipt, invocation = self.online_fixture()
        original = self.online_summary(receipt, invocation)['failureReceiptSha256']
        reordered = deployment.command_failure_summary({**invocation,
            'StandardOutputContent': json.dumps(dict(reversed(list(receipt.items()))), indent=2)})
        self.assertEqual(reordered['failureReceiptSha256'], original)
        changed = self.online_summary({**receipt, 'code': 'ONLINE_RECHARGE_ECR_LOGIN_FAILED'}, invocation)
        self.assertNotEqual(changed['failureReceiptSha256'], original)

    def test_online_failure_never_projects_unknown_code_even_with_allowed_prefix(self):
        receipt, invocation = self.online_fixture()
        for code in ('ONLINE_RECHARGE_FIXTURE_SENSITIVE_TOKEN', 'API_ADMIN_FIXTURE_SENSITIVE_TOKEN',
                     'ONLINE_RECHARGE_WORKER_KEY', 'ONLINE_RECHARGE_FAILURE_INVALID'):
            with self.subTest(code=code):
                result = self.online_summary({**receipt, 'code': code}, invocation)
                self.assertNotIn('candidateCommit', result)
                self.assertNotIn(code, json.dumps(result))

    def test_online_failure_requires_valid_requested_command_and_ended_failed_status(self):
        receipt, invocation = self.online_fixture()
        for field, values in (
                ('CommandId', [None, 'fixture-sensitive-token', invocation['CommandId'].upper(), 1]),
                ('Status', ['Success', 'Pending', 'InProgress', 'Cancelled', 'TimedOut', 'fixture-sensitive-token']),
                ('ResponseCode', [0, -1, 256, True, '1', None])):
            for value in values:
                with self.subTest(field=field, value=value):
                    self.assert_online_rejected(receipt, {**invocation, field: value})
        for value in ('', 'fixture-sensitive-token', '00000000-0000-0000-0000-000000000000'):
            with self.subTest(requested=value), patch.dict(deployment.os.environ, DIAGNOSTIC_COMMAND_ID=value):
                self.assert_online_rejected(receipt, invocation)

