    def fixture(self):
        policy = {'sourceAnchorSha256': 'a' * 64, 'metadataSha256': 'b' * 64,
            'sources': {'preserved': {'rowCount': 5, 'sha256': 'c' * 64}},
            'candidateBindings': {'sourceTree': 'd' * 40}}
