class FixedRegistrationEmailObservationTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        FixedRegistrationRuntimeScopeTests.setUpClass()
        cls.root = FixedRegistrationRuntimeScopeTests.root
        cls.runtime = cls.root / '.runtime/registration-email-submit-observation-release-20261006/remote-tests'
        cls.runtime.mkdir(parents=True, exist_ok=True)
        cls.profile = json.loads((cls.root / deployment.REGISTRATION_EMAIL_OBSERVATION_FILE).read_text())
        cls.profile['enabled'] = True
        cls.legacy = FixedRegistrationRuntimeScopeTests(); cls.legacy.runtime = cls.runtime

    def test_disabled_89_structural_baseline_keeps_actual88_and_six_immutable_profiles(self):
        pending = json.loads((self.root / deployment.REGISTRATION_EMAIL_OBSERVATION_FILE).read_text())
        if pending['enabled']:
            self.assertNotEqual(pending['registrationSourceCommit'], 'UNFROZEN')
        else:
            self.assertEqual(pending['registrationSourceCommit'], 'UNFROZEN')
            self.assertEqual(pending['workerProjectionSha256'], 'UNFROZEN')
        anchor = deployment.REGISTRATION_EMAIL_OBSERVATION_B91_BASELINE
        self.assertEqual(len(anchor['fileSha256']), 12)
        self.assertEqual(len(anchor['liveServices']), 7)
        self.assertEqual(len(anchor['readback']), 24)
