    def test_89_keeps_seven_source_pins_and_rejects_missing_extra_or_unreviewed_source(self):
        old = deployment.registration_contract(deployment.REGISTRATION_EMAIL_REQUEST_ID)
        self.assertEqual(set(self.profile['registrationSourceSha256']), set(old['sourceSha256']))
        self.assertEqual(len(self.profile['registrationSourceSha256']), 7)
        allowed = {deployment.REGISTRATION_WORKER_PREFIX + name for name in (
            'registration_browser.py', 'test_registration_browser.py')}
        for name, digest in self.profile['registrationSourceSha256'].items():
            if name not in allowed:
                self.assertEqual(digest, old['sourceSha256'][name])
        old_profile = json.loads((self.root / deployment.REGISTRATION_EMAIL_REQUEST_FILE).read_text())
        preserved = set(self.profile['workerProjection']) - allowed
        self.assertEqual(len(preserved), 58)
        for name in preserved:
            self.assertEqual(self.profile['workerProjection'][name], old_profile['workerProjection'][name])
        value = copy.deepcopy(self.profile)
        value['workerProjectionSha256'] = deployment.historical_fingerprint(value['workerProjection'])
        with patch.object(deployment, 'REGISTRATION_EMAIL_OBSERVATION_PROJECTION_SHA256', value['workerProjectionSha256']):
            self.assertEqual(deployment.registration_profile(value, profile_id=deployment.REGISTRATION_EMAIL_OBSERVATION_ID), value)
            missing = copy.deepcopy(value); del missing['registrationSourceSha256'][next(iter(allowed))]
            extra = copy.deepcopy(value); extra['registrationSourceSha256'][deployment.REGISTRATION_WORKER_PREFIX + 'unreviewed.py'] = 'a' * 64
            changed = copy.deepcopy(value); changed['registrationSourceSha256'][deployment.REGISTRATION_WORKER_PREFIX + 'registration_job.py'] = 'f' * 64
            projections = []
            for name in allowed:
                projection = copy.deepcopy(value); projection['workerProjection'][name]['sha256'] = 'f' * 64
                projections.append(projection)
            for mutated in (missing, extra, changed, *projections):
                with self.assertRaises(RuntimeError):
                    deployment.registration_profile(mutated, profile_id=deployment.REGISTRATION_EMAIL_OBSERVATION_ID)

