            for group, key, value in ((None, 'Id', 'd' * 64), ('State', 'Status', 'running'),
                    ('State', 'ExitCode', 0), ('State', 'ExitCode', False), ('Config', 'Env', None)):
                bad = copy.deepcopy(row)
