            stack.enter_context(patch.object(deployment, 'REGISTRATION_RECOVERY_BASELINE', baseline))
            stack.enter_context(patch.object(deployment, 'RECHARGE_2F_PROFILE_RAW', deployment.hashlib.sha256(raw92).hexdigest()))
